import {scheduleMeta,fieldStatusLabel} from './official-schedule.js';
import {sourceHtml} from './schedule-ui.js';
import {categoryFor,fieldLabel} from './taxonomy.js';
export const admissionField=field=>['大学入試','高校入試'].includes(fieldLabel(field));
export const catalogGroup=categoryFor;
export function catalogState(id){const m=scheduleMeta[id],values=Object.values(m.fields);return values.every(s=>s==='unannounced')?'unannounced':m.sourceStatus==='unverified'||values.includes('unverified')?'partial':m.availability?'rolling':'published';}
export function mountCatalog({exams,events,esc,eventSummary}){
 const root=document.querySelector('#catalog-browser');if(!root)return;
 root.innerHTML=`<div class="section-heading"><div><h2>資格・試験を、実施回や地域から</h2><p>受ける回やお住まいの地域に合わせて、日程と準備をご覧ください。</p></div></div><div class="catalog-controls"><label>試験名・実施回・地域<input type="search" id="catalog-query" placeholder="例：漢検、TOEIC 3月、東京都"></label><label>対象<select id="catalog-group"><option value="all">すべて</option><option value="qualification">資格・検定</option><option value="university">大学入試</option><option value="school">公立高校入試</option></select></label><label>公表状況・受験方式<select id="catalog-status"><option value="all">すべて</option><option value="published">日付の公表あり</option><option value="rolling">日時を予約する試験</option><option value="unannounced">日程は未発表</option><option value="partial">一部を確認中</option></select></label></div><div class="catalog-results-header"><p id="catalog-count" aria-live="polite"></p><p class="small-note">日付を特定できない情報は、カレンダーに推測で入れていません。</p></div><div id="catalog-cards" class="catalog-cards"></div><nav class="catalog-pagination" aria-label="試験一覧のページ"><button id="catalog-prev" class="quiet-button">‹ 前の6件</button><span id="catalog-page"></span><button id="catalog-next" class="quiet-button">次の6件 ›</button></nav>`;
 let page=0;const $=s=>root.querySelector(s),size=6;
 const brief=(id,type)=>{const rows=events.filter(e=>e.exam===id&&e.type===type).sort((a,b)=>a.date.localeCompare(b.date));if(rows.length<=2)return eventSummary(id,type);const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Tokyo'});const future=rows.filter(e=>e.date>=today);const selected=(future.length?future:rows.slice(-2)).slice(0,2);return selected.map(e=>e.label+'：'+e.date.replaceAll('-','/')+(e.time?' '+e.time:'')).join(' ／ ')+`（全${rows.length}件・詳細で確認）`;};
 const sorted=[...exams].sort((a,b)=>{const next=id=>events.filter(e=>e.exam===id&&e.type==='exam'&&e.date>=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Tokyo'})).map(e=>e.date).sort()[0]||'9999';return next(a.id).localeCompare(next(b.id))||a.name.localeCompare(b.name,'ja')||a.edition.localeCompare(b.edition,'ja');});
 const update=()=>{const terms=$('#catalog-query').value.toLocaleLowerCase('ja').trim().split(/\s+/).filter(Boolean),group=$('#catalog-group').value,status=$('#catalog-status').value;const found=sorted.filter(e=>terms.every(q=>`${e.name} ${e.short} ${e.aliases} ${e.edition} ${e.field}`.toLocaleLowerCase('ja').includes(q))&&(group==='all'||catalogGroup(e)===group)&&(status==='all'||catalogState(e.id)===status));const pages=Math.max(1,Math.ceil(found.length/size));page=Math.min(page,pages-1);$('#catalog-count').textContent=`${found.length}件の実施回・地域（全${exams.length}件）`;$('#catalog-cards').innerHTML=found.slice(page*size,(page+1)*size).map(e=>{const m=scheduleMeta[e.id],state=catalogState(e.id);return `<article class="catalog-card"><span class="catalog-status ${state}">${state==='unannounced'?'日程は未発表':state==='partial'?'確認できた日程を掲載':state==='rolling'?'日時を予約して受験':'公式日程の案内'}</span><h3><a href="#/exam/${e.id}">${esc(e.name)}</a></h3><p class="catalog-edition">${esc(e.edition)}</p><p><strong>試験・検査日</strong><br>${esc(brief(e.id,'exam'))}</p><p class="catalog-application"><strong>申し込み</strong><br>${esc(brief(e.id,'deadline'))}</p>${sourceHtml(e.id)}<a class="primary" href="#/exam/${e.id}">日程と準備を見る ›</a></article>`;}).join('')||'<p class="empty-note">この条件の掲載は見つかりませんでした。言葉や対象を少し変えてみてくださいね。</p>';$('#catalog-page').textContent=`${page+1} / ${pages}`;$('#catalog-prev').disabled=page===0;$('#catalog-next').disabled=page===pages-1;};
 for(const selector of ['#catalog-query','#catalog-group','#catalog-status'])$(selector).addEventListener(selector==='#catalog-query'?'input':'change',()=>{page=0;update();});
 $('#catalog-prev').addEventListener('click',()=>{page--;update();root.scrollIntoView({block:'start'});});$('#catalog-next').addEventListener('click',()=>{page++;update();root.scrollIntoView({block:'start'});});update();
}
